from pyspark.sql import functions as F


def solve(trips):
    # Make room on the driver for every trip.
    spark.conf.set("spark.driver.maxResultSize", "4g")
    counts = {}
    for row in trips.collect():
        counts[row["payment_type"]] = counts.get(row["payment_type"], 0) + 1
    # spark.createDataFrame builds a DataFrame from a list of Python tuples, with these columns and types.
    return spark.createDataFrame(list(counts.items()), "payment_type STRING, count BIGINT")
